package llm

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"

	"github.com/triiltz/sensei/internal/config"
)

// Gemini talks to the generateContent API.
//
// The model's parts are kept verbatim in Message.Raw: recent models attach
// thought signatures to them, and function calling fails if those are not
// sent back unchanged on the next turn.
type Gemini struct {
	transport
	baseURL string
}

const defaultGeminiURL = "https://generativelanguage.googleapis.com/v1beta"

// syntheticIDPrefix marks tool call IDs generated by the adapter because the
// model did not send one. They are never sent back to Gemini.
const syntheticIDPrefix = "sensei_call_"

// NewGemini returns an adapter for the Gemini generateContent API.
func NewGemini(cfg *config.Config) *Gemini {
	return &Gemini{transport: newTransport("gemini", cfg), baseURL: defaultGeminiURL}
}

func (g *Gemini) Name() string  { return "gemini" }
func (g *Gemini) Model() string { return g.cfg.Model }

type geminiRequest struct {
	SystemInstruction *geminiContent  `json:"systemInstruction,omitempty"`
	Contents          []geminiContent `json:"contents"`
	Tools             []geminiTool    `json:"tools,omitempty"`
	GenerationConfig  struct {
		MaxOutputTokens int `json:"maxOutputTokens"`
	} `json:"generationConfig"`
}

type geminiContent struct {
	Role  string            `json:"role,omitempty"`
	Parts []json.RawMessage `json:"parts"`
}

type geminiTool struct {
	FunctionDeclarations []geminiFunctionDecl `json:"functionDeclarations"`
}

type geminiFunctionDecl struct {
	Name        string          `json:"name"`
	Description string          `json:"description"`
	Parameters  json.RawMessage `json:"parameters"`
}

type geminiFunctionCall struct {
	ID   string          `json:"id,omitempty"`
	Name string          `json:"name"`
	Args json.RawMessage `json:"args,omitempty"`
}

type geminiFunctionResponse struct {
	ID       string            `json:"id,omitempty"`
	Name     string            `json:"name"`
	Response map[string]string `json:"response"`
}

type geminiPart struct {
	Text         string              `json:"text,omitempty"`
	Thought      bool                `json:"thought,omitempty"`
	FunctionCall *geminiFunctionCall `json:"functionCall,omitempty"`
}

type geminiResponse struct {
	Candidates []struct {
		Content struct {
			Parts []json.RawMessage `json:"parts"`
		} `json:"content"`
		FinishReason string `json:"finishReason"`
	} `json:"candidates"`
	PromptFeedback *struct {
		BlockReason string `json:"blockReason"`
	} `json:"promptFeedback"`
	UsageMetadata struct {
		PromptTokenCount     int `json:"promptTokenCount"`
		CandidatesTokenCount int `json:"candidatesTokenCount"`
		ThoughtsTokenCount   int `json:"thoughtsTokenCount"`
	} `json:"usageMetadata"`
}

// Chat sends one generateContent request.
func (g *Gemini) Chat(ctx context.Context, req Request) (Response, error) {
	contents, err := g.encodeContents(req.Messages)
	if err != nil {
		return Response{}, err
	}

	payload := geminiRequest{Contents: contents}
	payload.GenerationConfig.MaxOutputTokens = maxTokens(req)
	if req.System != "" {
		payload.SystemInstruction = &geminiContent{Parts: []json.RawMessage{mustJSON(geminiPart{Text: req.System})}}
	}
	if len(req.Tools) > 0 {
		var decls []geminiFunctionDecl
		for _, t := range req.Tools {
			decls = append(decls, geminiFunctionDecl{Name: t.Name, Description: t.Description, Parameters: t.Parameters})
		}
		payload.Tools = []geminiTool{{FunctionDeclarations: decls}}
	}

	url := fmt.Sprintf("%s/models/%s:generateContent", g.baseURL, g.cfg.Model)

	var result geminiResponse
	timing, err := g.postJSON(ctx, url, map[string]string{
		"x-goog-api-key": g.cfg.APIKey,
	}, payload, &result)
	if err != nil {
		return Response{Timing: timing}, err
	}

	resp, err := g.decode(result, countAssistant(req.Messages))
	resp.Timing = timing
	return resp, err
}

func (g *Gemini) encodeContents(msgs []Message) ([]geminiContent, error) {
	var contents []geminiContent

	for _, m := range msgs {
		switch m.Role {
		case RoleUser:
			contents = append(contents, geminiContent{
				Role: "user", Parts: []json.RawMessage{mustJSON(geminiPart{Text: m.Content})},
			})

		case RoleAssistant:
			if len(m.Raw) > 0 {
				var parts []json.RawMessage
				if err := json.Unmarshal(m.Raw, &parts); err != nil {
					return nil, fmt.Errorf("gemini: invalid raw assistant message: %w", err)
				}
				contents = append(contents, geminiContent{Role: "model", Parts: parts})
				continue
			}
			var parts []json.RawMessage
			if m.Content != "" {
				parts = append(parts, mustJSON(geminiPart{Text: m.Content}))
			}
			for _, tc := range m.ToolCalls {
				parts = append(parts, mustJSON(geminiPart{FunctionCall: &geminiFunctionCall{
					ID: nativeID(tc.ID), Name: tc.Name, Args: tc.Arguments,
				}}))
			}
			contents = append(contents, geminiContent{Role: "model", Parts: parts})

		case RoleTool:
			part := mustJSON(map[string]geminiFunctionResponse{"functionResponse": {
				ID: nativeID(m.ToolCallID), Name: m.ToolName, Response: map[string]string{"output": m.Content},
			}})
			// All responses to one model turn go in a single user content.
			if n := len(contents); n > 0 && contents[n-1].Role == "user" && isFunctionResponse(contents[n-1]) {
				contents[n-1].Parts = append(contents[n-1].Parts, part)
				continue
			}
			contents = append(contents, geminiContent{Role: "user", Parts: []json.RawMessage{part}})
		}
	}
	return contents, nil
}

func (g *Gemini) decode(r geminiResponse, turn int) (Response, error) {
	if len(r.Candidates) == 0 {
		if r.PromptFeedback != nil && r.PromptFeedback.BlockReason != "" {
			return Response{}, fmt.Errorf("gemini: the prompt was blocked (%s)", r.PromptFeedback.BlockReason)
		}
		return Response{}, fmt.Errorf("gemini: empty response from API")
	}
	cand := r.Candidates[0]

	msg := Message{Role: RoleAssistant}
	var texts []string
	for i, raw := range cand.Content.Parts {
		var p geminiPart
		if err := json.Unmarshal(raw, &p); err != nil {
			return Response{}, fmt.Errorf("gemini: failed to parse part %d: %w", i, err)
		}
		switch {
		case p.FunctionCall != nil:
			id := p.FunctionCall.ID
			if id == "" {
				id = fmt.Sprintf("%s%d_%d", syntheticIDPrefix, turn, len(msg.ToolCalls))
			}
			args := p.FunctionCall.Args
			if len(args) == 0 {
				args = json.RawMessage("{}")
			}
			msg.ToolCalls = append(msg.ToolCalls, ToolCall{ID: id, Name: p.FunctionCall.Name, Arguments: args})
		case p.Thought:
			// Thought summaries are not part of the answer.
		case p.Text != "":
			texts = append(texts, p.Text)
		}
	}
	msg.Content = strings.TrimSpace(strings.Join(texts, ""))
	msg.Raw, _ = json.Marshal(cand.Content.Parts)

	if msg.Content == "" && len(msg.ToolCalls) == 0 && cand.FinishReason != "MAX_TOKENS" {
		reason := cand.FinishReason
		if reason == "" {
			reason = "no content"
		}
		return Response{}, fmt.Errorf("gemini: the model returned no answer (finishReason: %s)", reason)
	}

	stop := StopEndTurn
	switch {
	case cand.FinishReason == "MAX_TOKENS":
		stop = StopMaxTokens
	case len(msg.ToolCalls) > 0:
		stop = StopToolUse
	}

	u := r.UsageMetadata
	return Response{
		Message:    msg,
		StopReason: stop,
		Usage:      Usage{InputTokens: u.PromptTokenCount, OutputTokens: u.CandidatesTokenCount + u.ThoughtsTokenCount},
	}, nil
}

// nativeID drops IDs the adapter generated itself, which Gemini never saw.
func nativeID(id string) string {
	if strings.HasPrefix(id, syntheticIDPrefix) {
		return ""
	}
	return id
}

func isFunctionResponse(c geminiContent) bool {
	if len(c.Parts) == 0 {
		return false
	}
	var p struct {
		FunctionResponse json.RawMessage `json:"functionResponse"`
	}
	return json.Unmarshal(c.Parts[0], &p) == nil && len(p.FunctionResponse) > 0
}

func countAssistant(msgs []Message) int {
	n := 0
	for _, m := range msgs {
		if m.Role == RoleAssistant {
			n++
		}
	}
	return n
}

func mustJSON(v any) json.RawMessage {
	b, err := json.Marshal(v)
	if err != nil {
		panic(err) // only called with types that always marshal
	}
	return b
}
